import bcryptjs from "bcryptjs";
import nodemailer from "nodemailer";
import { EmailOtp } from "./models/EmailOtp";
import { connectDB } from "./db";

const EMAIL_HOST = process.env.EMAIL_HOST || "smtp.gmail.com";
const EMAIL_PORT = parseInt(process.env.EMAIL_PORT || "587");
const EMAIL_USER = process.env.EMAIL_USER;
const EMAIL_PASS = process.env.EMAIL_PASS;
const NEXT_PUBLIC_BASE_URL = process.env.NEXT_PUBLIC_BASE_URL || "http://localhost:3000";
const IS_DEVELOPMENT = process.env.NODE_ENV !== "production";

let transporter: nodemailer.Transporter | null = null;

function getTransporter() {
  if (!transporter) {
    // In development, use a test account if email credentials are not provided
    if (IS_DEVELOPMENT && (!EMAIL_USER || !EMAIL_PASS)) {
      console.warn(
        "[OTP] Development mode: Email credentials not configured. OTP codes will be logged to console instead of sent."
      );
      // Return a test transporter that logs instead of sending
      return {
        sendMail: async (options: any) => {
          console.log(`[OTP] Development email output:`, options);
          return { accepted: [options.to] };
        },
      } as any;
    }

    if (!EMAIL_USER || !EMAIL_PASS) {
      throw new Error("Email configuration missing: EMAIL_USER and EMAIL_PASS required");
    }

    transporter = nodemailer.createTransport({
      host: EMAIL_HOST,
      port: EMAIL_PORT,
      secure: EMAIL_PORT === 465,
      auth: {
        user: EMAIL_USER,
        pass: EMAIL_PASS,
      },
    });
  }
  return transporter;
}

/**
 * Generate a random 6-digit OTP (100000-999999)
 */
export function generateOtpCode(): string {
  return Math.floor(100000 + Math.random() * 900000).toString();
}

/**
 * Hash an OTP code using bcrypt
 */
export async function hashOtpCode(code: string): Promise<string> {
  return bcryptjs.hash(code, 10);
}

/**
 * Compare OTP code with hash
 */
export async function compareOtpCode(code: string, hash: string): Promise<boolean> {
  return bcryptjs.compare(code, hash);
}

/**
 * Create and send OTP to email
 */
export async function createAndSendOtp(
  email: string,
  purpose: "signup" | "login"
): Promise<{ success: boolean; error?: string; devCode?: string }> {
  try {
    await connectDB();

    const code = generateOtpCode();
    const codeHash = await hashOtpCode(code);
    const expiresAt = new Date(Date.now() + 10 * 60 * 1000); // 10 minutes

    // Store OTP
    await EmailOtp.create({
      email: email.toLowerCase(),
      codeHash,
      purpose,
      expiresAt,
      used: false,
    });

    // Prepare email
    const transporter = getTransporter();
    const subject = purpose === "signup" ? "Verify your RNSTweets account" : "Login to RNSTweets";
    const html = `
      <div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">
        <h2>${subject}</h2>
        <p>Your one-time password is:</p>
        <h1 style="font-size: 32px; letter-spacing: 2px; color: #1DA1F2; font-weight: bold;">
          ${code}
        </h1>
        <p>This code expires in 10 minutes.</p>
        <p style="color: #666; font-size: 12px;">
          If you did not request this code, please ignore this email.
        </p>
      </div>
    `;

    // Log OTP in development mode where no email is configured
    if (IS_DEVELOPMENT && !EMAIL_USER) {
      console.log(`\n${"=".repeat(60)}`);
      console.log(`[OTP] ${purpose.toUpperCase()} OTP CODE FOR ${email}`);
      console.log(`${"=".repeat(60)}`);
      console.log(`OTP Code: ${code}`);
      console.log(`Expires at: ${expiresAt.toISOString()}`);
      console.log(`${"=".repeat(60)}\n`);
      return { success: true, devCode: code };
    }

    // Try to send email; if it fails and we're in development, fall back to logging the code
    try {
      await transporter.sendMail({
        from: EMAIL_USER || "noreply@rnstweets.local",
        to: email,
        subject,
        html,
      });

      console.log(`[OTP] Sent ${purpose} OTP to ${email}`);
      return { success: true };
    } catch (sendErr: any) {
      console.error(`[OTP] sendMail error:`, sendErr);
      if (IS_DEVELOPMENT) {
        console.warn("[OTP] sendMail failed in development — falling back to devCode response and logging");
        console.log(`\n${"=".repeat(60)}`);
        console.log(`[OTP] FALLBACK ${purpose.toUpperCase()} OTP CODE FOR ${email}`);
        console.log(`${"=".repeat(60)}`);
        console.log(`OTP Code: ${code}`);
        console.log(`Expires at: ${expiresAt.toISOString()}`);
        console.log(`${"=".repeat(60)}\n`);
        return { success: true, devCode: code, error: "Email delivery failed (dev fallback used)" };
      }

      return { success: false, error: "Email delivery failed" };
    }
  } catch (error: any) {
    console.error(`[OTP] Error creating/sending OTP:`, error);
    return { success: false, error: "Failed to create or send OTP" };
  }
}

/**
 * Verify OTP code
 */
export async function verifyOtp(
  email: string,
  purpose: "signup" | "login",
  code: string
): Promise<{ success: boolean; error?: string }> {
  try {
    await connectDB();

    const otp = (await EmailOtp.findOne({
      email: email.toLowerCase(),
      purpose,
      used: false,
    })
      .sort({ createdAt: -1 })
      .lean()) as any;

    if (!otp) {
      return { success: false, error: "OTP not found or already used" };
    }

    if (new Date() > new Date(otp.expiresAt)) {
      return { success: false, error: "OTP has expired" };
    }

    const isValid = await compareOtpCode(code, otp.codeHash);
    if (!isValid) {
      return { success: false, error: "Invalid OTP code" };
    }

    // Mark as used
    await EmailOtp.updateOne({ _id: otp._id }, { used: true });

    console.log(`[OTP] Verified ${purpose} OTP for ${email}`);
    return { success: true };
  } catch (error: any) {
    console.error(`[OTP] Error verifying OTP: ${error.message}`);
    return { success: false, error: error.message || "Failed to verify OTP" };
  }
}

/**
 * Resend OTP (invalidate old ones and create new)
 */
export async function resendOtp(
  email: string,
  purpose: "signup" | "login"
): Promise<{ success: boolean; error?: string }> {
  try {
    await connectDB();

    // Invalidate old unused OTPs
    await EmailOtp.updateMany(
      { email: email.toLowerCase(), purpose, used: false },
      { used: true }
    );

    // Create and send new one
    return createAndSendOtp(email, purpose);
  } catch (error: any) {
    console.error(`[OTP] Error resending OTP: ${error.message}`);
    return { success: false, error: error.message || "Failed to resend OTP" };
  }
}
